Method.Implementation:
Set startTS=..NormTS(pStart)
Set endTS=..NormTS(pEnd)

Write !!,"MessageCounter Rollups",!
Write "RangeStart=",startTS,!
Write "RangeEnd  =",endTS,!!

Kill monthCounts,weekCounts,excluded,indexUsed,sqlUsed,globalUsed
Set grandTotal=0

Kill nsList
Do ##class(%SYS.Namespace).ListAll(.nsList)

Set ns=""
For  {
    Set ns=$Order(nsList(ns))
    Quit:ns=""
    Continue:$Extract(ns,1,1)="%"

    ; switch namespace
    Set ok=1
    New $NAMESPACE
    Try { Set $NAMESPACE=ns } Catch ex { Set ok=0 }
    If 'ok {
        Set excluded(ns)="CANNOT ENTER NAMESPACE"
        Continue
    }

    If $Data(^Ens.MessageHeaderI("TimeCreated")) {
        Set indexUsed(ns)=""
        Do ..RollupFromIndex(startTS,endTS,.monthCounts,.weekCounts,.grandTotal)
        Continue
    }

    ; If no records at all, skip cleanly
    If $Order(^Ens.MessageHeaderD(""))="" {
        Set excluded(ns)="NO MESSAGE DATA"
        Continue
    }

    ; Try SQL rollup first (fast)
    Set okSQL=..RollupFromSQL(startTS,endTS,.monthCounts,.weekCounts,.grandTotal)
    If okSQL {
        Set sqlUsed(ns)=""
        Continue
    }

    ; Final fallback: global scan rollup
    Set okG=..RollupFromGlobal(startTS,endTS,.monthCounts,.weekCounts,.grandTotal)
    If okG {
        Set globalUsed(ns)=""
    } Else {
        Set excluded(ns)="NO TimeCreated INDEX; SQL failed; GLOBAL fallback failed"
    }
}

; ---- print months ----
Write "MONTHLY TOTALS",!
Write "Month",?15,"Count",!
Set mon=""
Set monthTotal=0
For  {
    Set mon=$Order(monthCounts(mon))
    Quit:mon=""
    Write mon,?15,+$Get(monthCounts(mon)),!
    Set monthTotal=monthTotal+$Get(monthCounts(mon))
}
Write "MONTH TOTAL",?15,monthTotal,!!

; ---- print weeks ----
Write "WEEKLY TOTALS (Monday start)",!
Write "Week Of",?15,"Week End",?30,"Count",!
Set wk=""
Set weekTotal=0
For  {
    Set wk=$Order(weekCounts(wk))
    Quit:wk=""

    Set wkH=$ZDATETIMEH(wk_" 00:00:00",3)
    Set wkDay=$Piece(wkH,",",1)
    Set wkEndStr=$ZDATE(wkDay+6,3)

    Write wk,?15,wkEndStr,?30,+$Get(weekCounts(wk)),!
    Set weekTotal=weekTotal+$Get(weekCounts(wk))
}
Write "WEEK TOTAL",?30,weekTotal,!!

; ---- totals check ----
Write "GRAND TOTAL",?15,grandTotal,!
Write "CHECK (months sum)",?15,monthTotal,!
Write "CHECK (weeks sum)",?15,weekTotal,!!

; ---- transparency ----
If $Data(indexUsed) {
    Write "NAMESPACES COUNTED VIA TimeCreated INDEX",!
    Set n=""
    For  { Set n=$Order(indexUsed(n)) Quit:n=""  Write n,! }
    Write !
}
If $Data(sqlUsed) {
    Write "NAMESPACES COUNTED VIA SQL FALLBACK",!
    Set n=""
    For  { Set n=$Order(sqlUsed(n)) Quit:n=""  Write n,! }
    Write !
}
If $Data(globalUsed) {
    Write "NAMESPACES COUNTED VIA GLOBAL FALLBACK",!
    Set n=""
    For  { Set n=$Order(globalUsed(n)) Quit:n=""  Write n,! }
    Write !
}
If $Data(excluded) {
    Write "EXCLUDED NAMESPACES (not counted)",!
    Set e=""
    For  { Set e=$Order(excluded(e)) Quit:e=""  Write e,": ",excluded(e),! }
    Write !
}

Quit

Set pStatus="" Set count=0
; switch namespace Set ok=1 New $NAMESPACE Try { Set $NAMESPACE=pNamespace } Catch ex { Set ok=0 } If 'ok { Set pStatus="CANNOT ENTER NAMESPACE" Quit 0 }
; Fast path If $Data(^Ens.MessageHeaderI("TimeCreated")) { Set count=..CountUsingIndex(pStartTS,pEndTS,.pStatus) Quit count }
; No message data at all? If $Order(^Ens.MessageHeaderD(""))="" { Set pStatus="NO MESSAGE DATA" Quit 0 }
; Try SQL Set count=..CountUsingSQL(pStartTS,pEndTS,.pStatus) If pStatus="OK (SQL)" Quit count
; Final fallback: global scan Set count=..CountUsingGlobal(pStartTS,pEndTS,.pStatus) Quit count

Set pStatus="OK (INDEX)"
Set count=0

Set minTS=$Order(^Ens.MessageHeaderI("TimeCreated",""))
Set maxTS=$Order(^Ens.MessageHeaderI("TimeCreated",""),-1)
If minTS="" { Set pStatus="TimeCreated INDEX EMPTY"  Quit 0 }
If (minTS ]] pEndTS) || (pStartTS ]] maxTS) { Set pStatus="OUTSIDE RANGE"  Quit 0 }

Set ts=""
For  {
    Set ts=$Order(^Ens.MessageHeaderI("TimeCreated",ts))
    Quit:ts=""

    Continue:(pStartTS ]] ts)
    Quit:(ts ]] pEndTS)

    Set id=""
    For  {
        Set id=$Order(^Ens.MessageHeaderI("TimeCreated",ts,id))
        Quit:id=""
        Set count=count+1
    }
}

Quit count

    Set pStatus="SQL FAILED"
    Set count=0

    Try {
        Set stmt=##class(%SQL.Statement).%New()
        Set sc=stmt.%Prepare("SELECT COUNT(*) FROM Ens.MessageHeader WHERE TimeCreated >= ? AND TimeCreated <= ?")
        If sc'=1 { Set pStatus="SQL PREPARE FAILED"  Goto Done }

        Set rset=stmt.%Execute(pStartTS,pEndTS)
        If rset.%Next() {
            Set count=+$Get(rset.%Get(1))
        } Else {
            Set count=0
        }
        Set pStatus="OK (SQL)"
    } Catch ex {
        Set pStatus="SQL EXECUTE ERROR"
        Set count=0
    }

Done
    Quit count

Set pStatus="OK (GLOBAL)"
Set count=0

Set id=""
Set prevTC=""
Set monotonic=1     ; assume monotonic until proven otherwise
Set seenInOrAfterStart=0

For  {
    Set id=$Order(^Ens.MessageHeaderD(id))
    Quit:id=""

    Set row=$Get(^Ens.MessageHeaderD(id))
    Continue:row=""

    ; TimeCreated is list piece 15 (validated in PROD SHEDI sample)
    Set tc=$ListGet(row,15)
    Continue:tc=""

    ; detect non-monotonicity (time went backwards)
    If prevTC'="" {
        If (prevTC ]] tc) Set monotonic=0
    }
    Set prevTC=tc

    ; skip before start: tc < start  <=> start sorts after tc
    If (pStartTS ]] tc) {
        Continue
    } Else {
        Set seenInOrAfterStart=1
    }

    ; past end: tc > end <=> tc sorts after end
    If (tc ]] pEndTS) {
        ; Early stop ONLY if (a) we’ve reached start already and (b) still monotonic
        If seenInOrAfterStart, monotonic {
            Quit
        } Else {
            Continue
        }
    }

    ; tc in [start,end]
    Set count=count+1
}

Quit count

    Set ok=1

    Try {
        ; months
        Set stmt=##class(%SQL.Statement).%New()
        Set sc=stmt.%Prepare("SELECT {fn SUBSTRING(TimeCreated,1,7)} AS mon, COUNT(*) AS cnt FROM Ens.MessageHeader WHERE TimeCreated >= ? AND TimeCreated <= ? GROUP BY {fn SUBSTRING(TimeCreated,1,7)} ORDER BY mon")
        If sc'=1 { Set ok=0  Goto Done }

        Set rset=stmt.%Execute(pStartTS,pEndTS)
        While rset.%Next() {
            Set mon=$Get(rset.%Get(1))
            Set cnt=+$Get(rset.%Get(2))
            If mon'="" {
                Set monthCounts(mon)=$Get(monthCounts(mon))+cnt
                Set grandTotal=grandTotal+cnt
            }
        }

        ; weeks (Monday start)
        Set stmt2=##class(%SQL.Statement).%New()
        Set sc2=stmt2.%Prepare("SELECT DATEADD('day', -MOD(DAYOFWEEK(TimeCreated)+5,7), CAST(TimeCreated AS DATE)) AS wkStart, COUNT(*) AS cnt FROM Ens.MessageHeader WHERE TimeCreated >= ? AND TimeCreated <= ? GROUP BY wkStart ORDER BY wkStart")
        If sc2'=1 { Set ok=0  Goto Done }

        Set rset2=stmt2.%Execute(pStartTS,pEndTS)
        While rset2.%Next() {
            Set wkStart=$Get(rset2.%Get(1))
            Set cnt=+$Get(rset2.%Get(2))
            If wkStart'="" {
                Set weekCounts(wkStart)=$Get(weekCounts(wkStart))+cnt
            }
        }

    } Catch ex {
        Set ok=0
    }

Done
    Quit ok
